export function experience(j){const t=j.requiredExperience||textOf(j);if(/no (?:prior )?experience|без опыта|0\s*[–-]\s*1|0\s*(?:years?|лет)/i.test(t))return 0;const m=t.match(/(?:at least\s*)?(\d+)\s*(?:\+|[–-]\s*\d+)?\s*(?:years?|лет|год|года)/i);return m?Number(m[1]):null}
function language(j){const t=textOf(j);const english=j.englishLevel||((t.match(/(?:english|англий\S*)\s*[:—–-]?\s*(A[12]|B[12]|C[12]|intermediate|fluent|advanced)/i)||[])[1])||((t.match(/(A[12]|B[12]|C[12])\s*(?:english|англий)/i)||[])[1])||'Unknown';const ge=j.georgianRequirement||(/(?:technical|advanced|C1|C2)\s+Georgian|Georgian.{0,30}(?:technical|advanced|C1|C2)/i.test(t)?'Technical advanced':/Georgian.{0,25}(required|fluent|native)|грузинск.{0,25}обяз/i.test(t)?'Conversational':'Unknown');const ru=j.russianRequirement||(/Russian.{0,25}(required|native|fluent)|русскоязыч/i.test(t)?'Required':'Unknown');const risks=[];if(/C[12]|advanced|fluent/i.test(english))risks.push('Английский выше рабочей цели B2');if(/technical|advanced|C[12]/i.test(ge))risks.push('Технический грузинский — риск');const known=english!=='Unknown'||ge!=='Unknown'||ru!=='Unknown';return{english,georgian:ge,russian:ru,risk:risks.join('; ')||(!known?'Языковые требования не указаны — уточнить':'Нет выявленных языковых рисков; B2 — цель, не подтверждённый сертификат'),fit:risks.length?'Risk':known?'Good fit':'Unknown',points:risks.length?2:known?10:5}}
