 const text=textOf(j),type=classifyType(j),intern=entryTypes.includes(type),profession=classifyProfession(j),professionPriority=professions.indexOf(profession)+1;
 const required=skillsIn(j.requiredStack||j.requirements||text);const known=skillsIn(profile.skills||'');const refresh=skillsIn(profile.refreshSkills||'Python, SQL, Git, Linux');const matching=required.filter(s=>known.includes(s));const needRefresh=required.filter(s=>refresh.includes(s));const missing=required.filter(s=>!known.includes(s)&&!refresh.includes(s));
