 const exp=experience(j),lang=language(j),senior=type==='Senior'||/\b(senior|lead|staff|principal)\b|старш|ведущ/i.test(j.title||'')||exp>=5;const targeted=required.filter(s=>['Python','SQL','PostgreSQL','ETL','ELT','Data pipelines','Airflow','dbt','Spark','Kafka','Docker','Git','Linux','REST API','Backend','Databases'].includes(s));
