export function compareJobs(a,b,profile={}){const x=evaluate(a,profile),y=evaluate(b,profile);const blocked=(j,s)=>s.excluded||j.availability==='closed'||['closed','archived','rejected'].includes(j.status)||s.category==='Poor match'?1:0;const lang=s=>s.language.fit==='Good fit'?0:s.language.fit==='Unknown'?1:2;const tech=s=>s.matching.length*4+s.parts.stack-s.missing.length;return blocked(a,x)-blocked(b,y)||levelPriority(a)-levelPriority(b)||x.professionPriority-y.professionPriority||x.formatPriority-y.formatPriority||lang(x)-lang(y)||tech(y)-tech(x)||(x.experience??2)-(y.experience??2)||y.score-x.score||(b.lastSignificantChange||foundDate(b)||'').localeCompare(a.lastSignificantChange||foundDate(a)||'')||String(a.id).localeCompare(String(b.id))}
export function todaySelection(jobs,profile,today){const pending=j=>!evaluate(j,profile).excluded&&!j.appliedAt&&!submittedStatuses.includes(j.status)&&!['closed','archived'].includes(j.status)&&j.availability!=='closed'&&(!j.deadline||j.deadline>=today);const manual=jobs.filter(j=>pending(j)&&(j.planDate===today||j.status==='apply_today'));const auto=jobs.filter(j=>{const s=evaluate(j,profile);return pending(j)&&!j.planDate&&j.dismissedToday!==today&&s.score>=65&&s.allowed&&!s.senior&&j.availability==='open'&&s.language.fit!=='Risk'&&!russiaPolicy(j).unknown}).sort((a,b)=>compareJobs(a,b,profile)).slice(0,Math.max(0,5-manual.length));return new Set([...manual,...auto].map(j=>j.id))}
