export function sourceOf(j){if(sources.includes(j.source))return j.source;try{const host=new URL(j.url).hostname;if(host.includes('linkedin.com'))return sources[0];if(host.includes('jobs.ge'))return sources[1];if(host.includes('hr.ge'))return sources[2];if(host.includes('wellfound.com'))return sources[3];if(host.includes('indeed.'))return sources[4];if(host.includes('startup.jobs'))return sources[5];if(/staff\.am|job\.am|careercenter\.am/.test(host))return 'Armenia job board';if(/findjobs\.ge|hrhub\.ge/.test(host))return 'Georgia job board';if(/remoteok|weworkremotely|remotive/.test(host))return 'Remote job board';return /career|lever|greenhouse|ashby|workday/i.test(j.url)?'Company careers':'Other'}catch{return sources[7]}}
